def select_next_node(current_node: int, destination_node: int, unvisited_nodes: np.ndarray, distance_matrix: np.ndarray) -> int:
    best_node = None
    best_score = float('inf')

    for candidate in unvisited_nodes:
        dist = distance_matrix[current_node, candidate]
        # Look-ahead penalty: after moving to candidate, find the minimum distance from candidate to any other unvisited node (excluding current_node)
        remaining = unvisited_nodes[unvisited_nodes != candidate]
        if len(remaining) > 0:
            min_future = np.min(distance_matrix[candidate][remaining])
        else:
            min_future = distance_matrix[candidate, destination_node]  # if last node, distance back to destination
        score = dist + 0.5 * min_future  # weighted combination
        if score < best_score:
            best_score = score
            best_node = candidate

    return best_node
